import{c as s,Q as n,j as p,m as t}from"./chunks/framework.DOi4mjdC.js";const d=JSON.parse('{"title":"算子原型定义","description":"","frontmatter":{},"headers":[{"level":1,"title":"算子原型定义","slug":"算子原型定义"},{"level":2,"title":"算子输入/输出/属性定义","slug":"算子输入输出属性定义"},{"level":2,"title":"AI处理器上相关实现信息","slug":"ai处理器上相关实现信息"},{"level":2,"title":"注册Tiling实现、Shape推导等函数","slug":"注册tiling实现shape推导等函数"},{"level":2,"title":"多硬件平台注册差异化的算子原型","slug":"多硬件平台注册差异化的算子原型"}],"relativePath":"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子原型定义.md","filePath":"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子原型定义.md"}'),l={name:"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子原型定义.md"};function e(i,a,o,g,c,u){return n(),p("div",null,[...a[0]||(a[0]=[t(`<h1 id="算子原型定义" tabindex="-1">算子原型定义 <a class="header-anchor" href="#算子原型定义" aria-label="Permalink to &quot;算子原型定义&quot;">​</a></h1><p>算子原型主要描述了算子的输入输出、属性等信息以及算子在AI处理器上相关实现信息，并关联<a href="./Host侧Tiling实现/基本流程.html">tiling实现</a>等函数。算子原型通过自定义的算子类来承载，该算子类继承自OpDef类。完成算子的原型定义等操作后，需要调用OP_ADD接口，传入算子类型（自定义算子类的类名），进行算子原型注册。下面是一个简单的Add算子原型定义和注册的例子。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>namespace ops {</span></span>
<span class="line"><span>class AddCustom : public OpDef {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    AddCustom(const char* name) : OpDef(name)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        this-&gt;Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Input(&quot;y&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Output(&quot;z&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        // 如下的shape/datatype推导函数仅在算子入图场景使用</span></span>
<span class="line"><span>        this-&gt;SetInferShape(ge::InferShape);</span></span>
<span class="line"><span>        this-&gt;SetInferDataType(ge::InferDataType);  </span></span>
<span class="line"><span>        this-&gt;AICore()</span></span>
<span class="line"><span>            .SetTiling(optiling::TilingFunc);</span></span>
<span class="line"><span>        // 请替换为实际的昇腾AI处理器型号</span></span>
<span class="line"><span>        this-&gt;AICore().AddConfig(&quot;ascendxxx&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>OP_ADD(AddCustom);</span></span>
<span class="line"><span>} // namespace ops</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>基于算子原型定义，自定义算子工程可以实现如下自动化能力： <ul><li>自动生成<a href="./单算子API调用.html">单算子API调用</a>的实现和接口，开发者可以直接使用生成的API实现单算子调用。</li><li>自动生成图模式场景使用的算子原型定义REG_OP，开发者可以使用生成的算子原型进行构图、图编译、图执行等操作。</li></ul></li><li>注册算子类型后，框架会根据算子类型获取算子注册信息，同时在编译和运行时按照一定的规则匹配算子实现文件名称和kernel侧核函数名称。为了保证正确匹配，算子类型、算子实现文件名称和核函数名称需要遵循如下定义规则。通常情况下，开发者只需要保证创建算子工程时原型定义json文件中算子类型op的参数值为大驼峰命名方式即可，工程创建后自动生成的代码即满足该规则。在手动编写算子原型定义和算子实现文件时需要按照如下规则定义。 <ul><li>算子类型需要采用<strong>大驼峰</strong>的命名方式，即采用大写字符区分不同的语义。</li><li>算子实现文件名称、核函数名称需相同，均为算子类型转换为<strong>下划线</strong>命名方式后的值。下文描述了通过算子类型转换成算子实现文件名称和核函数名称的过程： <ul><li>首字符的大写字符转换为小写字符。例如：Abc -&gt; abc。</li><li>大写字符的前一个字符为小写字符或数字，则在大写字符前插一个下划线“_”，并将该字符转换为小写字符。例如：AbcDef -&gt; abc_def。</li><li>大写字符前一个字符为大写字符且后一个字符是小写字符，则在大写字符前插一个下划线“_”，并将该字符转换为小写字符。例如：AbcAAc -&gt; abc_a_ac。</li><li>其他大写字符转换为小写字符，小写字符保持不变。</li></ul></li></ul></li></ul></div><h2 id="算子输入-输出-属性定义" tabindex="-1">算子输入/输出/属性定义 <a class="header-anchor" href="#算子输入-输出-属性定义" aria-label="Permalink to &quot;算子输入/输出/属性定义&quot;">​</a></h2><p>算子原型定义描述了算子的输入输出、属性等信息。输入输出支持的datatype、format格式的数量需要一致，并保持一一对应的关系。</p><p>如下的代码片段呈现了Add算子输入x的描述信息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        this-&gt;Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span></code></pre></div><p><strong>表 1</strong> 输入输出参数说明</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;12.93%&quot;&gt;&lt;p&gt;原型定义&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.580000000000002%&quot;&gt;&lt;p&gt;参数&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;72.49%&quot;&gt;&lt;p&gt;具体描述&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; rowspan=&quot;3&quot; valign=&quot;top&quot; width=&quot;12.93%&quot;&gt;&lt;p&gt;Input/Output&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.580000000000002%&quot;&gt;&lt;p&gt;ParamType&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;72.49%&quot;&gt;&lt;p&gt;参数类型，Option取值为：OPTIONAL（可选）、REQUIRED（必选）、DYNAMIC（动态输入）。&lt;/p&gt; &lt;ul&gt;&lt;li&gt;类似于上文中的Add样例，其输入输出是必选的。&lt;/li&gt;&lt;li&gt;有些算子的输入或者输出个数是动态的，例如AddN，将N个输入Tensor累加到一起，输出一个Tensor；SplitV，将一个Tensor在某个轴上，拆分为N个Tensor输出。&lt;/li&gt;&lt;li&gt;有些算子的输入/输出是可选的，例如BatchNorm算子，在训练的时候没有均值和方差输入，在推理的时候有均值和方差的输入。&lt;/li&gt;&lt;/ul&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;DataType&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;算子输入输出支持的datatype。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;Format&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;算子输入输出支持的format。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>从上文的原型定义中可以看出，列出了输入输出所有datatype和format的组合，保持一一对应。使用如下接口，可以达到简化这种代码逻辑的目的。</p><ul><li><p>在指定输入/输出的datatype信息时，如果某个输入/输出的datatype支持和其他所有输入/输出的datatype/format组合使用，其datatype可以通过DataTypeList来表达；在指定输入/输出的format信息时，如果某个输入/输出的format支持和其他所有输入/输出的datatype/format组合使用，其format可以通过FormatList来表达。示例如下，以下两种代码表达含义相同。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 列出所有一一对应的组合</span></span>
<span class="line"><span>class XxxCustom : public OpDef {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    XxxCustom(const char* name) : OpDef(name)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        this-&gt;Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_FLOAT16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Input(&quot;y&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Output(&quot;z&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        ...</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>// 通过DataTypeList和FormatList来表达，无需重复列出</span></span>
<span class="line"><span>class XxxCustom : public OpDef {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    XxxCustom(const char* name) : OpDef(name)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        this-&gt;Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataTypeList({ge::DT_FLOAT16})</span></span>
<span class="line"><span>            .FormatList({ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Input(&quot;y&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Output(&quot;z&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        ...</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>};</span></span></code></pre></div></li><li><p>通过Follow接口指定当前输入/输出的datatype/format/shape信息与之前定义过的某个输入一致。示例如下：输出“y1”Follow输入“x1”场景，此时“y1”的datatype、format以及shape都将会和“x1”保持一致。使用Follow接口指定shape一致时通常比<a href="./../算子入图开发/基本开发流程.html#section358205411221">shape推导</a>函数逻辑更加简单，能用Follow表达的逻辑，建议使用Follow接口，则无需再编写注册InferShape函数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>this-&gt;Input(&quot;x1&quot;)</span></span>
<span class="line"><span>    .ParamType(REQUIRED)</span></span>
<span class="line"><span>    .DataType({ge::DT_FLOAT, ge::DT_FLOAT})</span></span>
<span class="line"><span>    .Format({ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>this-&gt;Input(&quot;x2&quot;)</span></span>
<span class="line"><span>    .ParamType(REQUIRED)</span></span>
<span class="line"><span>    .DataType({ge::DT_FLOAT, ge::DT_FLOAT})</span></span>
<span class="line"><span>    .Format({ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>this-&gt;Output(&quot;y1&quot;)</span></span>
<span class="line"><span>    .ParamType(REQUIRED)</span></span>
<span class="line"><span>    .Follow(&quot;x1&quot;)</span></span>
<span class="line"><span>    .OutputShapeDependOnCompute();</span></span></code></pre></div></li></ul><p>原型定义中还包括算子属性信息，如下的代码片段呈现了ReduceMax算子的属性reduceDim和isKeepDim的描述信息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        this-&gt;Attr(&quot;reduceDim&quot;)</span></span>
<span class="line"><span>            .AttrType(REQUIRED)</span></span>
<span class="line"><span>            .Int();</span></span>
<span class="line"><span>        this-&gt;Attr(&quot;isKeepDim&quot;)</span></span>
<span class="line"><span>            .AttrType(OPTIONAL)</span></span>
<span class="line"><span>            .Int(1);</span></span></code></pre></div><p>具体参数说明如下：</p><p><strong>表 2</strong> 属性参数说明</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;12.93%&quot;&gt;&lt;p&gt;原型定义&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.580000000000002%&quot;&gt;&lt;p&gt;注册方式&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;72.49%&quot;&gt;&lt;p&gt;具体描述&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; rowspan=&quot;2&quot; valign=&quot;top&quot; width=&quot;12.93%&quot;&gt;&lt;p&gt;Attr&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.580000000000002%&quot;&gt;&lt;p&gt;AttrType&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;72.49%&quot;&gt;&lt;p&gt;设置算子属性类型，取值为：OPTIONAL（可选）、REQUIRED（必选）。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;Bool/Float/Int...&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;设置算子属性数据类型为Bool/Float/Int...。具体说明请参考OpAttrDef。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><h2 id="ai处理器上相关实现信息" tabindex="-1">AI处理器上相关实现信息 <a class="header-anchor" href="#ai处理器上相关实现信息" aria-label="Permalink to &quot;AI处理器上相关实现信息&quot;">​</a></h2><p>通过AddConfig注册算子支持的AI处理器型号以及相关的配置信息。AddConfig接口原型如下：soc参数表示AI处理器型号，aicore_config表示其他配置信息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void AddConfig(const char *soc);</span></span>
<span class="line"><span>void AddConfig(const char *soc, OpAICoreConfig &amp;aicore_config);</span></span></code></pre></div><p>通过该接口注册AI处理器型号的样例如下，ascendxxx填写规则请参考算子工程目录下编译配置项文件CMakePresets.json中的ASCEND_COMPUTE_UNIT字段，该字段取值在<a href="./创建算子工程.html">使用msOpGen创建工程</a>时自动生成。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        this-&gt;AICore().AddConfig(&quot;ascendxxx&quot;);</span></span></code></pre></div><p>其他AI Core配置信息的配置方式请参考OpAICoreConfig。</p><h2 id="注册tiling实现、shape推导等函数" tabindex="-1">注册Tiling实现、Shape推导等函数 <a class="header-anchor" href="#注册tiling实现、shape推导等函数" aria-label="Permalink to &quot;注册Tiling实现、Shape推导等函数&quot;">​</a></h2><p>通过SetInferShape、SetInferDataType、SetTiling接口来注册对应的Tiling实现和Shape推导等函数，样例如下。注册的Tiling实现等函数由框架侧进行调用，并在调用时传入对应的Context上下文，供开发者使用。Tiling函数的实现方法请参考<a href="./Host侧Tiling实现/基本流程.html">Host侧Tiling实现</a>，入图相关的Shape推导等函数实现请参考<a href="./../算子入图开发/概述.html">算子入图开发</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        // 如下的shape/datatype推导函数仅在算子入图场景使用       </span></span>
<span class="line"><span>        this-&gt;SetInferShape(ge::InferShape);</span></span>
<span class="line"><span>        this-&gt;SetInferDataType(ge::InferDataType);</span></span>
<span class="line"><span>        this-&gt;AICore()</span></span>
<span class="line"><span>            .SetTiling(optiling::TilingFunc);</span></span></code></pre></div><h2 id="多硬件平台注册差异化的算子原型" tabindex="-1">多硬件平台注册差异化的算子原型 <a class="header-anchor" href="#多硬件平台注册差异化的算子原型" aria-label="Permalink to &quot;多硬件平台注册差异化的算子原型&quot;">​</a></h2><p>算子类继承基类OpDef，使用Input、Output、Attr等注册算子原型信息，硬件平台支持相同的算子原型的情况下，直接通过AICore().AddConfig添加支持的AI处理器型号即可；不同的硬件形态算子原型定义不同的情况，可以通过新增OpAICoreConfig的方式，针对不同的AI处理器型号注册差异化的算子原型。</p><p>差异化的算子原型生效规则如下：</p><ul><li>对于算子类的输入输出原型信息，OpAICoreConfig未配置的会继承OpDef定义的原型，比如算子类中定义了输出y，OpAICoreConfig中没有定义输出y，OpAICoreConfig会继承y的原型定义；</li><li>对于算子类和新增OpAICoreConfig中定义的算子原型相同的情况，新增OpAICoreConfig中定义的算子原型信息会覆盖OpDef定义的原型信息，比如算子类中定义了输入x支持DT_FLOAT16数据类型，新增OpAICoreConfig中也定义了输入x，但是支持DT_FLOAT16、DT_BF16数据类型，则以OpAICoreConfig新增定义为准。</li></ul><p>如下样例中ascendxxx1、ascendxxx2（AI处理器型号）使用相同的算子原型，算子类通过继承基类OpDef，使用Input、Output、Attr等注册算子原型信息，再通过AICore().AddConfig添加支持的AI处理器型号；对于ascendxxx3支持的算子原型需要定制化处理，新增了DT_BF16的类型，通过新增OpAICoreConfig的方式进行注册，x，y，z的定义会覆盖算子类中对应定义的原型信息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>namespace ops {</span></span>
<span class="line"><span>class MyAdd : public OpDef {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    MyAdd(const char* name) : OpDef(name)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        // ascendxxx1 ascendxxx2 AI处理器型号原型定义</span></span>
<span class="line"><span>        this-&gt;Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Input(&quot;y&quot;)</span></span>
<span class="line"><span>            .ParamType(OPTIONAL)</span></span>
<span class="line"><span>            .DataType({ge::DT_INT64})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Output(&quot;z&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;AICore()</span></span>
<span class="line"><span>            .SetTiling(optiling::TilingFunc);</span></span>
<span class="line"><span>        this-&gt;AICore().AddConfig(&quot;ascendxxx1&quot;);</span></span>
<span class="line"><span>        this-&gt;AICore().AddConfig(&quot;ascendxxx2&quot;);</span></span>
<span class="line"><span>        // ascendxxx3 AI处理器定义OpAICoreConfig变量，定制化原型</span></span>
<span class="line"><span>        OpAICoreConfig config;</span></span>
<span class="line"><span>        config.Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_BF16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        config.Input(&quot;y&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_BF16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        config.Output(&quot;z&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_BF16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;AICore().AddConfig(&quot;ascendxxx3&quot;, config);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>OP_ADD(MyAdd);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如下的样例中，只有几个参数原型信息在不同硬件平台不一致，开发者也可以通过OpAICoreConfig定制部分算子原型信息，复用OpDef定义的其他算子原型信息，达到部分原型信息硬件平台定制化的目的。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>class AddCustom : public OpDef {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    AddCustom(const char* name) : OpDef(name)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        this-&gt;Input(&quot;x&quot;).DataType({ ge::DT_FLOAT16 }).ParamType(OPTIONAL);</span></span>
<span class="line"><span>        this-&gt;Output(&quot;y&quot;).DataType({ ge::DT_FLOAT16 });</span></span>
<span class="line"><span>        OpAICoreConfig aicConfig1;</span></span>
<span class="line"><span>        OpAICoreConfig aicConfig2;</span></span>
<span class="line"><span>        aicConfig1.Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(OPTIONAL)</span></span>
<span class="line"><span>            .DataType({ ge::DT_FLOAT })</span></span>
<span class="line"><span>            .Format({ ge::FORMAT_ND });</span></span>
<span class="line"><span>        aicConfig2.Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ ge::DT_INT32 })</span></span>
<span class="line"><span>            .Format({ ge::FORMAT_ND });</span></span>
<span class="line"><span>        this-&gt;AICore().AddConfig(&quot;ascendxxx1&quot;, aicConfig1);</span></span>
<span class="line"><span>        this-&gt;AICore().AddConfig(&quot;ascendxxx2&quot;, aicConfig2);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>};</span></span></code></pre></div>`,34)])])}const T=s(l,[["render",e]]);export{d as __pageData,T as default};
